  ('audit.view', 'View the audit trail');

-- Role -> permission bundles (architecture/06 §2). Bundles are additive per the doc's
-- "X bundle + ..." language (e.g. Cashier = wait-staff bundle + payment/settlement permissions).
-- `order.void.execute` is bundled with Cashier: the doc lists void/discount/etc. as separate
-- execute-vs-approve permissions but does not name every execute-side holder explicitly; a
-- cashier is the natural front-line holder of "execute", with Unit supervisor holding
-- "approve" — called out as an interpretation in the PR description.

INSERT INTO role_permission (role_id, permission_id)
SELECT r.id, p.id FROM role r, permission p
WHERE r.code = 'WAIT_STAFF' AND p.code IN
  ('order.create','order.line.add','order.line.remove_unsent','order.send','tab.view_own_facility');

INSERT INTO role_permission (role_id, permission_id)
SELECT r.id, p.id FROM role r, permission p
WHERE r.code = 'BARTENDER' AND p.code IN
  ('order.create','prep_ticket.view','prep_ticket.transition');

INSERT INTO role_permission (role_id, permission_id)
SELECT r.id, p.id FROM role r, permission p
WHERE r.code = 'KITCHEN_STAFF' AND p.code IN
  ('prep_ticket.view','prep_ticket.transition');

