WHERE r.code = 'CASHIER' AND p.code IN
  ('order.create','order.line.add','order.line.remove_unsent','order.send','tab.view_own_facility',
   'order.void.execute','payment.take','payment.split','order.settle',
   'cash_session.open','cash_session.close','receipt.reprint');

